-- Candidate migration64; filename generated by official CLI in Actions42486198366.
-- Observation/review only. No refund API, automatic licence policy, fiscal
-- emission, worker activation or changes to immutable migrations62/63.
create table private.tc_subscription_financial_cases(
 id uuid primary key default gen_random_uuid(),
 task_id uuid not null unique references private.tc_manual_subscription_invoice_tasks(id) on delete restrict,
 provider_account_id text not null check(provider_account_id ~ '^acct_[A-Za-z0-9]{1,100}$'),
 mode text not null check(mode in ('test','live')),
 payment_intent_id text not null check(payment_intent_id ~ '^pi_[A-Za-z0-9]{1,200}$'),
 charge_id text not null check(charge_id ~ '^ch_[A-Za-z0-9]{1,200}$'),
 created_at timestamptz not null default now(),
 unique(provider_account_id,mode,payment_intent_id),
 unique(provider_account_id,mode,charge_id)
);
create table private.tc_subscription_financial_entries(
 id uuid primary key default gen_random_uuid(),
 case_id uuid not null references private.tc_subscription_financial_cases(id) on delete restrict,
 row_version bigint not null check(row_version between 2 and 9007199254740991),
 kind text not null check(kind in ('provider','review','rectification_report')),
 actor_id uuid references auth.users(id) on delete restrict,
 operation_id uuid unique,
 expected_version bigint,
 provider_event_id text unique check(provider_event_id ~ '^evt_[A-Za-z0-9]{1,200}$'),
 event_proof_sha256 text check(event_proof_sha256 ~ '^[a-f0-9]{64}$'),
 data jsonb not null check(jsonb_typeof(data)='object' and octet_length(data::text)<=12000),
 created_at timestamptz not null default now(),
 unique(case_id,row_version),
 check((kind='provider' and actor_id is null and operation_id is null and expected_version is null
   and provider_event_id is not null and event_proof_sha256 is not null)
  or (kind<>'provider' and actor_id is not null and operation_id is not null
   and expected_version is not null and expected_version=row_version-1
   and provider_event_id is null and event_proof_sha256 is null))
);
create index tc_subscription_financial_entries_case_idx
 on private.tc_subscription_financial_entries(case_id,row_version desc);
create unique index tc_subscription_financial_rectification_reference_unique
 on private.tc_subscription_financial_entries(upper(btrim(data->>'reference')))
 where kind='rectification_report';
alter table private.tc_subscription_financial_cases enable row level security;
alter table private.tc_subscription_financial_entries enable row level security;
revoke all on private.tc_subscription_financial_cases,private.tc_subscription_financial_entries
 from public,anon,authenticated,service_role;
create policy tc_subscription_financial_cases_private
 on private.tc_subscription_financial_cases as restrictive for all to public using(false) with check(false);
create policy tc_subscription_financial_entries_private
 on private.tc_subscription_financial_entries as restrictive for all to public using(false) with check(false);
create trigger tc_subscription_financial_cases_immutable
 before update or delete or truncate on private.tc_subscription_financial_cases
 for each statement execute function private.tc_manual_subscription_intake_reject_mutation();
create trigger tc_subscription_financial_entries_immutable
 before update or delete or truncate on private.tc_subscription_financial_entries
 for each statement execute function private.tc_manual_subscription_intake_reject_mutation();

create function private.tc_subscription_incident_integer(p_value jsonb,p_min bigint,p_max bigint)
returns boolean language sql immutable set search_path='' as $integer$
 select case when jsonb_typeof(p_value)='number' then
  (p_value#>>'{}')::numeric between p_min and p_max
  and trunc((p_value#>>'{}')::numeric)=(p_value#>>'{}')::numeric else false end;
$integer$;
revoke all on function private.tc_subscription_incident_integer(jsonb,bigint,bigint)
 from public,anon,authenticated,service_role;

-- READ ONLY: reconstruct the original63 digest, never grant access on event ID alone.
create function private.tc_manual_subscription_known_payment_event(
 p_account text,p_mode text,p_event jsonb
) returns jsonb language plpgsql stable security definer set search_path='' as $known$
declare r private.tc_payment_requests; t private.tc_manual_subscription_invoice_tasks;
 receipt private.tc_manual_stripe_bridge_receipts; digest text; event_type text; stamp bigint;
 resource text; checkout text;
begin
 if current_setting('role',true) is distinct from 'service_role' then
  raise exception 'subscription_incident_server_only' using errcode='42501';end if;
 if p_account is null or p_account !~ '^acct_[A-Za-z0-9]{1,100}$'
  or p_mode is null or p_mode not in ('test','live') or jsonb_typeof(p_event) is distinct from 'object'
  or p_event-array['id','type','created','resource_id']<>'{}'
  or not (p_event ?& array['id','type','created','resource_id'])
  or p_event->>'id' is null or p_event->>'id' !~ '^evt_[A-Za-z0-9]{1,200}$'
  or not private.tc_subscription_incident_integer(p_event->'created',1,9007199254740991) then
  raise exception 'subscription_incident_invalid' using errcode='22023';end if;
 event_type:=p_event->>'type';stamp:=(p_event->>'created')::bigint;resource:=p_event->>'resource_id';
 if stamp>extract(epoch from now())+300 then
  raise exception 'subscription_incident_invalid' using errcode='22023';end if;
 select * into receipt from private.tc_manual_stripe_bridge_receipts x where x.provider_event_id=p_event->>'id';
 if not found then return jsonb_build_object('contract','manual-stripe-known-payment-event-v1','known',false);end if;
 select * into t from private.tc_manual_subscription_invoice_tasks x where x.id=receipt.task_id;
 select * into r from private.tc_payment_requests x where x.id=t.request_id;
 if receipt.provider_account_id is distinct from p_account or receipt.mode is distinct from p_mode
  or receipt.request_id is distinct from t.request_id or r.id is null
  or t.provider_account_id is distinct from receipt.provider_account_id
  or t.provider_payment_id is distinct from receipt.provider_payment_id
  or r.user_id is distinct from t.buyer_user_id then
  raise exception 'subscription_incident_conflicting_replay' using errcode='23514';end if;
 if receipt.payment_kind='initial_payment' then
  if event_type is null or event_type not in ('checkout.session.completed','checkout.session.async_payment_succeeded')
   or resource is null or resource !~ '^cs_[A-Za-z0-9_]{1,200}$'
   or resource is distinct from r.checkout_id or t.provider_invoice_id is not null
   or t.provider_payment_id !~ '^pi_[A-Za-z0-9]{1,200}$' then
   raise exception 'subscription_incident_conflicting_replay' using errcode='23514';end if;
  checkout:=r.checkout_id;
 elsif receipt.payment_kind='subscription_invoice' then
  if event_type is distinct from 'invoice.paid' or resource is distinct from t.provider_invoice_id
   or t.provider_payment_id is distinct from t.provider_invoice_id or t.subscription_id is null
   or t.period_start is null or t.period_end is null then
   raise exception 'subscription_incident_conflicting_replay' using errcode='23514';end if;
  -- In63 checkout_id is assigned only in the initial_payment branch.
  checkout:=null;
 else raise exception 'subscription_incident_conflicting_replay' using errcode='23514';end if;
 digest:=encode(sha256(convert_to(jsonb_build_object(
  'kind',receipt.payment_kind,'account',p_account,'mode',p_mode,'event',receipt.provider_event_id,
  'type',event_type,'event_created',stamp,'payment',t.provider_payment_id,
  'request',t.request_id,'user',t.buyer_user_id,'company',t.buyer_company_id,
  'amount',t.amount_cents,'currency','EUR','paid_at',extract(epoch from t.paid_at),'checkout',checkout,
  'invoice',t.provider_invoice_id,'subscription',t.subscription_id,
  'start',extract(epoch from t.period_start),'end',extract(epoch from t.period_end)
 )::text,'UTF8')),'hex');
 if digest is distinct from receipt.proof_sha256 then
  raise exception 'subscription_incident_conflicting_replay' using errcode='23514';end if;
 return jsonb_build_object('contract','manual-stripe-known-payment-event-v1','known',true);
end;$known$;
revoke all on function private.tc_manual_subscription_known_payment_event(text,text,jsonb)
 from public,anon,authenticated;
create function public.tc_manual_subscription_known_payment_event(p_account text,p_mode text,p_event jsonb)
returns jsonb language sql stable security invoker set search_path='' as $known_wrapper$
 select private.tc_manual_subscription_known_payment_event(p_account,p_mode,p_event);
$known_wrapper$;
revoke all on function public.tc_manual_subscription_known_payment_event(text,text,jsonb) from public,anon,authenticated;
grant execute on function private.tc_manual_subscription_known_payment_event(text,text,jsonb),
 public.tc_manual_subscription_known_payment_event(text,text,jsonb) to service_role;

create function private.tc_subscription_incident_provider_dto(p_data jsonb,p_observed timestamptz)
returns jsonb language sql stable set search_path='' as $provider_dto$
 select jsonb_build_object(
  'event_id',p_data->>'event_id','event_type',p_data->>'event_type',
  'object_id',p_data->>'object_id','object_type',p_data->>'object_type',
  'status_at_event',p_data->>'status_at_event','current_status',p_data->>'current_status',
  'event_amount_cents',(p_data->>'event_amount_cents')::integer,
  'current_amount_cents',(p_data->>'current_amount_cents')::integer,
  'charge_amount_refunded_cents',(p_data->>'charge_amount_refunded_cents')::integer,
  'extent',case when (p_data->>'current_amount_cents')::integer=0 then 'none'
   when (p_data->>'current_amount_cents')::integer<(p_data->>'charge_amount_cents')::integer then 'partial'
   when (p_data->>'current_amount_cents')::integer=(p_data->>'charge_amount_cents')::integer then 'full' else 'mismatch' end,
  'event_created',to_timestamp((p_data->>'event_created')::bigint),'observed_at',p_observed,
  'payment_intent_id',p_data->>'payment_intent_id','charge_id',p_data->>'charge_id'
 );
$provider_dto$;
revoke all on function private.tc_subscription_incident_provider_dto(jsonb,timestamptz)
 from public,anon,authenticated,service_role;

create function private.tc_subscription_incident_entry_dto(p_entry private.tc_subscription_financial_entries)
returns jsonb language sql stable set search_path='' as $entry_dto$
 select jsonb_build_object('id',p_entry.id,'row_version',p_entry.row_version,'kind',p_entry.kind,
  'actor_id',p_entry.actor_id,'created_at',p_entry.created_at,
  'provider',case when p_entry.kind='provider' then private.tc_subscription_incident_provider_dto(p_entry.data,p_entry.created_at) else null end,
  'note',case when p_entry.kind<>'provider' then p_entry.data->>'note' else null end,
  'reference',case when p_entry.kind='rectification_report' then p_entry.data->>'reference' else null end);
$entry_dto$;
revoke all on function private.tc_subscription_incident_entry_dto(private.tc_subscription_financial_entries)
 from public,anon,authenticated,service_role;

create function private.tc_subscription_incident_case_dto(p_case uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $case_dto$
declare c private.tc_subscription_financial_cases;t private.tc_manual_subscription_invoice_tasks;
 observation private.tc_subscription_financial_entries;review private.tc_subscription_financial_entries;
 rectification private.tc_subscription_financial_entries;version bigint;
begin
 select * into c from private.tc_subscription_financial_cases where id=p_case;
 select * into t from private.tc_manual_subscription_invoice_tasks where id=c.task_id;
 select * into observation from private.tc_subscription_financial_entries where case_id=c.id and kind='provider' order by row_version desc limit 1;
 select * into review from private.tc_subscription_financial_entries where case_id=c.id and kind='review' order by row_version desc limit 1;
 select * into rectification from private.tc_subscription_financial_entries where case_id=c.id and kind='rectification_report' order by row_version desc limit 1;
 select max(row_version) into version from private.tc_subscription_financial_entries where case_id=c.id;
 if c.id is null or observation.id is null then raise exception 'subscription_incident_not_found' using errcode='42501';end if;
 return jsonb_build_object(
  'id',c.id,'task_id',t.id,'buyer_company_id',t.buyer_company_id,'buyer_company_name',t.buyer_company_name,
  'provider_payment_id',t.provider_payment_id,'provider_invoice_id',t.provider_invoice_id,
  'period_start',t.period_start,'period_end',t.period_end,'amount_cents',t.amount_cents,'currency',t.currency,
  'paid_at',t.paid_at,'row_version',version,'created_at',c.created_at,
  'review_state',case when coalesce(review.row_version,0)>observation.row_version then 'reviewed' else 'pending' end,
  'rectification_state',case when coalesce(rectification.row_version,0)>observation.row_version then 'reported' else 'pending' end,
  'latest_provider',private.tc_subscription_incident_provider_dto(observation.data,observation.created_at),
  'last_review',case when review.id is null then null else jsonb_build_object(
   'note',review.data->>'note','actor_id',review.actor_id,'reported_at',review.created_at,'row_version',review.row_version) end,
  'rectification',case when rectification.id is null then null else jsonb_build_object(
   'reference',rectification.data->>'reference','note',rectification.data->>'note','actor_id',rectification.actor_id,
   'reported_at',rectification.created_at,'row_version',rectification.row_version) end
 );
end;$case_dto$;
revoke all on function private.tc_subscription_incident_case_dto(uuid) from public,anon,authenticated,service_role;

-- Provider observations are attributed only to an already reconciled payment.
-- No tenant/user/task ID is accepted from the HTTP payload or mutable metadata.
create function private.tc_manual_subscription_record_incident(p_account text,p_mode text,p_data jsonb)
returns jsonb language plpgsql security definer set search_path='' as $record$
#variable_conflict use_variable
declare
 c private.tc_subscription_financial_cases;t private.tc_manual_subscription_invoice_tasks;
 existing private.tc_subscription_financial_entries;case_uuid uuid;task_uuid uuid;matches integer;
 key text;kind text;event_type text;stamp bigint;proof jsonb;digest text;version bigint;
 invoice_id text;intent_id text;charge_id text;amount integer;
begin
 if current_setting('role',true) is distinct from 'service_role' then
  raise exception 'subscription_incident_server_only' using errcode='42501';end if;
 if p_account is null or p_account !~ '^acct_[A-Za-z0-9]{1,100}$'
  or p_mode is null or p_mode not in ('test','live') or jsonb_typeof(p_data) is distinct from 'object'
  or octet_length(p_data::text)>12000
  or p_data-array['event_id','event_type','event_created','livemode','currency','object_type','object_id',
    'status_at_event','current_status','event_amount_cents','current_amount_cents','charge_amount_cents',
    'charge_amount_refunded_cents','event_amount_refunded_cents','payment_intent_id','charge_id','customer_id',
    'invoice_id','subscription_id','invoice_payment_id','invoice_period_start','invoice_period_end','invoice_amount_cents']<>'{}'
  or not (p_data ?& array['event_id','event_type','event_created','livemode','currency','object_type','object_id',
    'status_at_event','current_status','event_amount_cents','current_amount_cents','charge_amount_cents',
    'charge_amount_refunded_cents','event_amount_refunded_cents','payment_intent_id','charge_id','customer_id',
    'invoice_id','subscription_id','invoice_payment_id','invoice_period_start','invoice_period_end','invoice_amount_cents'])
  or jsonb_typeof(p_data->'livemode') is distinct from 'boolean'
  or (p_data->>'livemode')::boolean is distinct from (p_mode='live')
  or p_data->>'currency' is distinct from 'EUR'
  or p_data->>'event_id' is null or p_data->>'event_id' !~ '^evt_[A-Za-z0-9]{1,200}$'
  or p_data->>'payment_intent_id' is null or p_data->>'payment_intent_id' !~ '^pi_[A-Za-z0-9]{1,200}$'
  or p_data->>'charge_id' is null or p_data->>'charge_id' !~ '^ch_[A-Za-z0-9]{1,200}$'
  or not private.tc_subscription_incident_integer(p_data->'event_created',1,9007199254740991)
 then raise exception 'subscription_incident_invalid' using errcode='22023';end if;
 foreach key in array array['event_amount_cents','current_amount_cents','charge_amount_cents','charge_amount_refunded_cents'] loop
  if not private.tc_subscription_incident_integer(p_data->key,0,100000000) then
   raise exception 'subscription_incident_invalid' using errcode='22023';end if;
 end loop;
 foreach key in array array['status_at_event','current_status'] loop
  if p_data->>key is null or p_data->>key !~ '^[a-z_]{1,64}$' then
   raise exception 'subscription_incident_invalid' using errcode='22023';end if;
 end loop;
 stamp:=(p_data->>'event_created')::bigint;kind:=p_data->>'object_type';event_type:=p_data->>'event_type';
 intent_id:=p_data->>'payment_intent_id';charge_id:=p_data->>'charge_id';invoice_id:=p_data->>'invoice_id';
 amount:=(p_data->>'charge_amount_cents')::integer;
 if stamp>extract(epoch from now())+300 or amount<1
  or (p_data->>'charge_amount_refunded_cents')::integer>amount
  or event_type is null or event_type not in ('charge.refunded','refund.created','refund.updated','refund.failed',
   'charge.dispute.created','charge.dispute.updated','charge.dispute.closed')
  or kind is null or kind not in ('refund','dispute','charge')
  or p_data->>'object_id' is null
  or (kind='refund' and (event_type not like 'refund.%' or p_data->>'object_id' !~ '^re_[A-Za-z0-9]{1,200}$'))
  or (kind='dispute' and (event_type not like 'charge.dispute.%' or p_data->>'object_id' !~ '^du_[A-Za-z0-9]{1,200}$'))
  or (kind='charge' and (event_type<>'charge.refunded' or p_data->>'object_id'<>charge_id))
  or (p_data->>'customer_id' is not null and p_data->>'customer_id' !~ '^cus_[A-Za-z0-9]{1,200}$') then
  raise exception 'subscription_incident_invalid' using errcode='23514';end if;
 if kind='refund' and (
    p_data->>'status_at_event' not in ('pending','requires_action','succeeded','failed','canceled')
    or p_data->>'current_status' not in ('pending','requires_action','succeeded','failed','canceled')
    or (p_data->>'event_amount_cents')::integer<1
    or p_data->'event_amount_cents' is distinct from p_data->'current_amount_cents'
    or (p_data->>'current_amount_cents')::integer>amount
    or (event_type='refund.failed' and p_data->>'status_at_event'<>'failed')
    or jsonb_typeof(p_data->'event_amount_refunded_cents') is distinct from 'null')
  or kind='dispute' and (
    p_data->>'status_at_event' not in ('warning_needs_response','warning_under_review','warning_closed','needs_response','under_review','won','lost')
    or p_data->>'current_status' not in ('warning_needs_response','warning_under_review','warning_closed','needs_response','under_review','won','lost')
    or (p_data->>'event_amount_cents')::integer<1 or (p_data->>'current_amount_cents')::integer<1
    or (event_type='charge.dispute.closed' and p_data->>'status_at_event' not in ('warning_closed','won','lost'))
    or jsonb_typeof(p_data->'event_amount_refunded_cents') is distinct from 'null')
  or kind='charge' and (
    p_data->>'status_at_event'<>'succeeded' or p_data->>'current_status'<>'succeeded'
    or not private.tc_subscription_incident_integer(p_data->'event_amount_refunded_cents',0,amount)
    or p_data->'event_amount_refunded_cents' is distinct from p_data->'event_amount_cents'
    or p_data->'current_amount_cents' is distinct from p_data->'charge_amount_refunded_cents')
 then raise exception 'subscription_incident_invalid' using errcode='23514';end if;

 -- Distinct tasks, not delivery count: several accepted events can bind one payment.
 select count(distinct x.id),min(x.id::text)::uuid into matches,task_uuid
 from private.tc_manual_subscription_invoice_tasks x
 join private.tc_manual_stripe_bridge_receipts r on r.task_id=x.id
 where x.provider_account_id=p_account and r.provider_account_id=p_account and r.mode=p_mode
  and ((invoice_id is null and x.provider_invoice_id is null and x.provider_payment_id=intent_id and r.payment_kind='initial_payment')
    or (invoice_id is not null and x.provider_invoice_id=invoice_id and x.provider_payment_id=invoice_id and r.payment_kind='subscription_invoice'));
 if matches<>1 or task_uuid is null then
  raise exception 'subscription_incident_mapping_review' using errcode='23514';end if;
 -- Same task lock order for provider deliveries; original rows are never updated.
 select * into t from private.tc_manual_subscription_invoice_tasks x where x.id=task_uuid for update;
 if t.amount_cents<>amount or t.currency<>'EUR' then
  raise exception 'subscription_incident_payment_mismatch' using errcode='23514';end if;
 if invoice_id is null then
  if jsonb_typeof(p_data->'subscription_id') is distinct from 'null'
   or jsonb_typeof(p_data->'invoice_payment_id') is distinct from 'null'
   or jsonb_typeof(p_data->'invoice_period_start') is distinct from 'null'
   or jsonb_typeof(p_data->'invoice_period_end') is distinct from 'null'
   or jsonb_typeof(p_data->'invoice_amount_cents') is distinct from 'null' then
   raise exception 'subscription_incident_payment_mismatch' using errcode='23514';end if;
 else
  if invoice_id !~ '^in_[A-Za-z0-9]{1,200}$'
   or p_data->>'subscription_id' is distinct from t.subscription_id
   or p_data->>'invoice_payment_id' is null or p_data->>'invoice_payment_id' !~ '^inpay_[A-Za-z0-9]{1,200}$'
   or not private.tc_subscription_incident_integer(p_data->'invoice_period_start',1,9007199254740991)
   or not private.tc_subscription_incident_integer(p_data->'invoice_period_end',1,9007199254740991)
   or not private.tc_subscription_incident_integer(p_data->'invoice_amount_cents',1,100000000)
   or (p_data->>'invoice_period_start')::bigint is distinct from extract(epoch from t.period_start)::bigint
   or (p_data->>'invoice_period_end')::bigint is distinct from extract(epoch from t.period_end)::bigint
   or (p_data->>'invoice_amount_cents')::integer<>t.amount_cents
   or not exists(select 1 from private.tc_subscription_invoices i
     join private.tc_billing_subscriptions b on b.provider_id=i.subscription_id
     where i.invoice_id=invoice_id and i.subscription_id=t.subscription_id and i.user_id=t.buyer_user_id
      and i.amount_cents=t.amount_cents and i.period_start=t.period_start and i.period_end=t.period_end
      and b.request_id=t.request_id and b.customer_id=p_data->>'customer_id') then
   raise exception 'subscription_incident_payment_mismatch' using errcode='23514';end if;
 end if;
 -- Only immutable event projection participates in idempotence. A later GET
 -- status/cumulative amount can change; it never rewrites an earlier observation.
 proof:=jsonb_build_object('account',p_account,'mode',p_mode,'event_id',p_data->'event_id',
  'event_type',event_type,'event_created',stamp,'currency','EUR','object_type',kind,'object_id',p_data->'object_id',
  'status_at_event',p_data->'status_at_event','event_amount_cents',p_data->'event_amount_cents',
  'event_amount_refunded_cents',p_data->'event_amount_refunded_cents','payment_intent_id',intent_id,
  'charge_id',charge_id,'invoice_id',invoice_id,'subscription_id',p_data->'subscription_id');
 digest:=encode(sha256(convert_to(proof::text,'UTF8')),'hex');
 select * into existing from private.tc_subscription_financial_entries where provider_event_id=p_data->>'event_id';
 select * into c from private.tc_subscription_financial_cases where task_id=t.id for update;
 if c.id is null then
  insert into private.tc_subscription_financial_cases(task_id,provider_account_id,mode,payment_intent_id,charge_id)
   values(t.id,p_account,p_mode,intent_id,charge_id) returning * into c;
 end if;
 if c.provider_account_id<>p_account or c.mode<>p_mode or c.payment_intent_id<>intent_id or c.charge_id<>charge_id then
  raise exception 'subscription_incident_payment_mismatch' using errcode='23514';end if;
 if existing.id is not null then
  if existing.case_id<>c.id or existing.event_proof_sha256<>digest then
   raise exception 'subscription_incident_conflicting_replay' using errcode='23514';end if;
  return jsonb_build_object('contract','subscription-financial-incidents-record-v1','received',true,'duplicate',true,'case_id',c.id);
 end if;
 select coalesce(max(row_version),1)+1 into version from private.tc_subscription_financial_entries where case_id=c.id;
 insert into private.tc_subscription_financial_entries(case_id,row_version,kind,provider_event_id,event_proof_sha256,data)
  values(c.id,version,'provider',p_data->>'event_id',digest,p_data);
 return jsonb_build_object('contract','subscription-financial-incidents-record-v1','received',true,'duplicate',false,'case_id',c.id);
end;$record$;
revoke all on function private.tc_manual_subscription_record_incident(text,text,jsonb) from public,anon,authenticated;
create function public.tc_manual_subscription_record_incident(p_account text,p_mode text,p_data jsonb)
returns jsonb language sql security invoker set search_path='' as $record_wrapper$
 select private.tc_manual_subscription_record_incident(p_account,p_mode,p_data);
$record_wrapper$;
revoke all on function public.tc_manual_subscription_record_incident(text,text,jsonb) from public,anon,authenticated;
grant execute on function private.tc_manual_subscription_record_incident(text,text,jsonb),
 public.tc_manual_subscription_record_incident(text,text,jsonb) to service_role;

create function private.tc_subscription_incident_operation(p_entry private.tc_subscription_financial_entries)
returns jsonb language sql stable set search_path='' as $operation$
 select jsonb_build_object('id',p_entry.operation_id,
  'action',case when p_entry.kind='review' then 'review' else 'report_rectification' end,
  'expected_version',p_entry.expected_version,'applied_version',p_entry.row_version,'actor_id',p_entry.actor_id,
  'reported_at',p_entry.created_at,'note',p_entry.data->>'note','reference',p_entry.data->>'reference');
$operation$;
revoke all on function private.tc_subscription_incident_operation(private.tc_subscription_financial_entries)
 from public,anon,authenticated,service_role;

create function private.tc_admin_subscription_incidents(
 p_action text,p_case_id uuid default null,p_expected bigint default null,
 p_operation_id uuid default null,p_data jsonb default '{}',p_after uuid default null
) returns jsonb language plpgsql security definer set search_path='' as $admin$
declare actor uuid;c private.tc_subscription_financial_cases;
 previous private.tc_subscription_financial_entries;inserted private.tc_subscription_financial_entries;
 rows jsonb;tail uuid;before_version bigint;next_before bigint;version bigint;entry_kind text;note text;reference text;
begin
 actor:=private.tc_manual_subscription_operator();
 if p_data is null or jsonb_typeof(p_data)<>'object' or octet_length(p_data::text)>8192 then
  raise exception 'subscription_incident_invalid' using errcode='22023';end if;
 if p_action='capabilities' then
  return jsonb_build_object('contract','subscription-financial-incidents-v1','available',true,
   'refunds_available',false,'license_changes_available',false,'rectification_emission_available',false);
 end if;
 if p_action in ('list','detail') then
  if p_data<>'{}' or (p_action='detail' and p_case_id is null) then
   raise exception 'subscription_incident_invalid' using errcode='22023';end if;
  select coalesce(jsonb_agg(private.tc_subscription_incident_case_dto(q.id) order by q.id),'[]') into rows
  from (select id from private.tc_subscription_financial_cases
   where (p_action<>'detail' or id=p_case_id) and (p_after is null or id>p_after) order by id limit 50) q;
  tail:=case when jsonb_array_length(rows)=50 then (rows->49->>'id')::uuid else null end;
  return jsonb_build_object('contract','subscription-financial-incidents-v1','items',rows,'next_cursor',tail);
 end if;
 if p_action='history' then
  if p_case_id is null or p_data-array['before_version']<>'{}'
   or (p_data ? 'before_version' and not private.tc_subscription_incident_integer(p_data->'before_version',1,9007199254740991)) then
   raise exception 'subscription_incident_invalid' using errcode='22023';end if;
  if not exists(select 1 from private.tc_subscription_financial_cases where id=p_case_id) then
   raise exception 'subscription_incident_not_found' using errcode='42501';end if;
  before_version:=(p_data->>'before_version')::bigint;
  select coalesce(jsonb_agg(private.tc_subscription_incident_entry_dto(q::private.tc_subscription_financial_entries) order by q.row_version desc),'[]') into rows
  from (select * from private.tc_subscription_financial_entries
   where case_id=p_case_id and (before_version is null or row_version<before_version)
   order by row_version desc limit 50) q;
  next_before:=case when jsonb_array_length(rows)=50 then (rows->49->>'row_version')::bigint else null end;
  return jsonb_build_object('contract','subscription-financial-incidents-v1','case_id',p_case_id,'items',rows,'next_before_version',next_before);
 end if;
 if p_action is null or p_action not in ('review','report_rectification')
  or p_case_id is null or p_operation_id is null or p_expected is null
  or p_expected<1 or p_expected>=9007199254740991 then
  raise exception 'subscription_incident_invalid' using errcode='22023';end if;
 note:=p_data->>'note';reference:=p_data->>'reference';
 if jsonb_typeof(p_data->'note') is distinct from 'string'
  or char_length(btrim(note)) not between 3 and 1000
  or note ~ '[[:cntrl:]]'
  or (p_action='review' and p_data-array['note']<>'{}')
  or (p_action='report_rectification' and (p_data-array['note','reference']<>'{}'
    or jsonb_typeof(p_data->'reference') is distinct from 'string'
    or char_length(btrim(reference)) not between 1 and 200 or reference ~ '[[:cntrl:]]')) then
  raise exception 'subscription_incident_invalid' using errcode='22023';end if;
 -- Preserve supplied bytes for replay: client validation trims before sending.
 if note<>btrim(note) or (p_action='report_rectification' and reference<>btrim(reference)) then
  raise exception 'subscription_incident_invalid' using errcode='22023';end if;
 select * into c from private.tc_subscription_financial_cases where id=p_case_id for update;
 if not found then raise exception 'subscription_incident_not_found' using errcode='42501';end if;
 actor:=private.tc_manual_subscription_operator();
 entry_kind:=case when p_action='review' then 'review' else 'rectification_report' end;
 select * into previous from private.tc_subscription_financial_entries where operation_id=p_operation_id;
 if found then
  if previous.case_id<>p_case_id or previous.actor_id<>actor or previous.kind<>entry_kind
   or previous.expected_version<>p_expected or previous.data<>p_data then
   raise exception 'subscription_incident_conflicting_replay' using errcode='23514';end if;
  return jsonb_build_object('contract','subscription-financial-incidents-v1','case',private.tc_subscription_incident_case_dto(c.id),
   'replayed',true,'operation',private.tc_subscription_incident_operation(previous));
 end if;
 select coalesce(max(row_version),1) into version from private.tc_subscription_financial_entries where case_id=c.id;
 if version<>p_expected then raise exception 'subscription_incident_version_conflict' using errcode='40001';end if;
 begin
  insert into private.tc_subscription_financial_entries(case_id,row_version,kind,actor_id,operation_id,expected_version,data)
   values(c.id,version+1,entry_kind,actor,p_operation_id,version,p_data) returning * into inserted;
 exception when unique_violation then
  raise exception 'subscription_incident_reference_conflict' using errcode='23514';
 end;
 return jsonb_build_object('contract','subscription-financial-incidents-v1','case',private.tc_subscription_incident_case_dto(c.id),
  'replayed',false,'operation',private.tc_subscription_incident_operation(inserted));
end;$admin$;
revoke all on function private.tc_admin_subscription_incidents(text,uuid,bigint,uuid,jsonb,uuid)
 from public,anon,authenticated,service_role;
grant execute on function private.tc_admin_subscription_incidents(text,uuid,bigint,uuid,jsonb,uuid) to authenticated;
create function public.tc_admin_subscription_incidents(
 p_action text,p_case_id uuid default null,p_expected bigint default null,
 p_operation_id uuid default null,p_data jsonb default '{}',p_after uuid default null
) returns jsonb language sql security invoker set search_path='' as $admin_wrapper$
 select private.tc_admin_subscription_incidents(p_action,p_case_id,p_expected,p_operation_id,p_data,p_after);
$admin_wrapper$;
revoke all on function public.tc_admin_subscription_incidents(text,uuid,bigint,uuid,jsonb,uuid) from public,anon,service_role;
grant execute on function public.tc_admin_subscription_incidents(text,uuid,bigint,uuid,jsonb,uuid) to authenticated;
